107						b.Fatal(err)
108					}
109				}
110			})
111			offset := benchRoller(time.Second, 0)
112			base := time.Unix(int64(n), 0)
113			for i := 0; i < n; i++ {
114				if err := offset.Add(base.Add(time.Duration(i)*time.Second), float64(i)); err != nil {
