119				b.ReportAllocs()
120				for i := 0; i < b.N; i++ {
121					b.StopTimer()
122					dst := benchRoller(time.Second, n)
123					b.StartTimer()
124					if err := dst.Merge(offset); err != nil {
125						b.Fatal(err)
126					}
127				}
128			})
129		}
130	}
