297	// TestConcurrentAddBatch files batches from many goroutines while others
298	// read snapshots and advance cursors; every accepted batch must be
299	// accounted for exactly once, and no snapshot may show a partial batch.
300	// Run with -race to catch data races.
301	func TestConcurrentAddBatch(t *testing.T) {
302		r := New(2500 * time.Millisecond)
303		const writers = 8
304		const perWriter = 100
305		const batchSize = 4
306	
307		stop := make(chan struct{})
308		var readers sync.WaitGroup
309		for i := 0; i < 2; i++ {
310			readers.Add(1)
311			go func() {
312				defer readers.Done()
313				for {
314					select {
315					case <-stop:
316						return
317					default:
318					}
319					for _, w := range r.Windows() {
320						if w.Count <= 0 || w.Min > w.Max {
321							t.Errorf("inconsistent snapshot: %+v", w)
322						}
323					}
324					c := r.Cursor(time.Unix(0, 0), time.Unix(1<<40, 0))
325					for got := c.Next(7); len(got) != 0; got = c.Next(7) {
326						for _, w := range got {
327							if w.Count <= 0 || w.Min > w.Max {
328								t.Errorf("inconsistent cursor window: %+v", w)
329							}
330						}
331					}
332				}
333			}()
334		}
335	
336		// Each writer submits batches of batchSize samples at one instant per
337		// batch; every sample in an accepted batch lands in the same window.
338		var accepted atomic.Int64
339		var writersWg sync.WaitGroup
340		for w := 0; w < writers; w++ {
341			writersWg.Add(1)
342			go func(w int) {
343				defer writersWg.Done()
344				for i := 0; i < perWriter; i++ {
345					at := time.Unix(0, int64(i)*int64(2500*time.Millisecond)+int64(w))
346					batch := make([]Sample, batchSize)
347					for k := range batch {
348						batch[k] = Sample{At: at, Value: float64(w)}
349					}
350					err := r.AddBatch(batch)
351					switch {
352					case err == nil:
353						accepted.Add(batchSize)
354					case errors.Is(err, ErrOutOfOrder):
355						// Lost the race to a later batch; fine.
356					default:
357						t.Errorf("AddBatch: %v", err)
358					}
359				}
360			}(w)
361		}
362		writersWg.Wait()
363		close(stop)
364		readers.Wait()
365	
366		var total int64
367		for _, w := range r.Windows() {
368			total += w.Count
369		}
370		if total != accepted.Load() {
371			t.Fatalf("total count = %d, want %d accepted samples", total, accepted.Load())
372		}
373	}
374	
375	// BenchmarkAddBatch measures sustained batch submission; each batch opens
376	// new windows, and the cost should scale with the batch size.
377	func BenchmarkAddBatch(b *testing.B) {
378		for _, size := range []int{1, 16, 256} {
379			b.Run(fmt.Sprintf("size=%d", size), func(b *testing.B) {
380				r := New(time.Second)
381				base := time.Unix(0, 0)
382				batch := make([]Sample, size)
383				b.ReportAllocs()
384				b.ResetTimer()
385				for i := 0; i < b.N; i++ {
386					start := base.Add(time.Duration(i*size) * time.Second)
387					for k := range batch {
388						batch[k] = Sample{At: start.Add(time.Duration(k) * time.Second), Value: float64(k)}
389					}
390					if err := r.AddBatch(batch); err != nil {
391						b.Fatal(err)
392					}
393				}
394			})
395		}
396	}
