50		if !ok {
51			t.Fatal("sample at -1s should fall in window starting at -10s")
52		}
53		if w.Count != 1 || w.Sum != 5 {
54			t.Fatalf("window -10: %+v", w)
55		}
56	}
57	
58	func TestOutOfOrder(t *testing.T) {
59		r := New(time.Minute)
60		if err := r.Add(time.Unix(120, 0), 1); err != nil {
61			t.Fatal(err)
62		}
63		if err := r.Add(time.Unix(119, 0), 1); !errors.Is(err, ErrOutOfOrder) {
64			t.Fatalf("expected ErrOutOfOrder, got %v", err)
65		}
66		// State unchanged by the rejection.
67		w, _ := r.Window(time.Unix(120, 0))
68		if w.Count != 1 {
69			t.Fatalf("rejected sample mutated state: %+v", w)
70		}
71		// Same instant is accepted and counted again.
72		if err := r.Add(time.Unix(120, 0), 2); err != nil {
73			t.Fatal(err)
74		}
