113		if w.Count != 3 || w.Sum != 14 || w.Min != 1 || w.Max != 10 {
114			t.Fatalf("merged window: %+v", w)
115		}
116		if _, ok := a.Window(time.Unix(60, 0)); !ok {
117			t.Fatal("other-only window not carried over")
118		}
119		// Merging the same stats twice counts them twice.
120		if err := a.Merge(b); err != nil {
121			t.Fatal(err)
122		}
123		w, _ = a.Window(time.Unix(0, 0))
124		if w.Count != 4 || w.Sum != 24 {
125			t.Fatalf("double merge: %+v", w)
126		}
127		// Merge does not affect out-of-order tracking.
128		if err := a.Add(time.Unix(0, 0), 0); err != nil {
129			t.Fatalf("add after merge: %v", err)
130		}
131	}
132	
133	func TestMergeMismatchAndNil(t *testing.T) {
134		a := New(time.Minute)
135		a.Add(time.Unix(0, 0), 1)
136		if err := a.Merge(New(time.Hour)); !errors.Is(err, ErrWindowMismatch) {
137			t.Fatalf("expected ErrWindowMismatch, got %v", err)
138		}
139		if got := len(a.Windows()); got != 1 {
140			t.Fatalf("failed merge mutated receiver: %d windows", got)
141		}
142		defer func() {
143			if r := recover(); r != "rollup: nil roller" {
144				t.Fatalf("panic = %v", r)
145			}
146		}()
147		a.Merge(nil)
148	}
149	
150	func TestBadWindowPanics(t *testing.T) {
151		for _, d := range []time.Duration{0, -time.Second} {
152			func() {
153				defer func() {
154					if r := recover(); r != "rollup: bad window" {
155						t.Fatalf("panic = %v", r)
156					}
157				}()
158				New(d)
159			}()
160		}
161	}
