298		// Several valid windows followed by a bad line: nothing is printed and
299		// no state survives the process anyway, but stdout must be empty.
300		content := "0 1\n100 2\n50 3\n"
301		got := runWithFile(t, content, "--window", "100ns", "windows")
302		if got.code != 4 || got.stdout != "" {
303			t.Fatalf("code = %d, stdout = %q, stderr = %q", got.code, got.stdout, got.stderr)
304		}
305	}
