308		got := runWithFile(t, "0 1\n", "--window", "1ns", "-")
309		if got.code != 2 {
310			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
311		}
312	}
313	
314	func TestRunEndOfFlags(t *testing.T) {
315		// After -- the subcommand is positional, but flags before it still
316		// apply.
317		content := "0 1\n"
318		got := runWithFile(t, content, "--window", "1s", "--", "windows")
319		if got.code != 0 {
320			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
321		}
322	}
323	
324	func TestFormatFloatRoundTrip(t *testing.T) {
325		// Every distinct float64 in a dense sweep round-trips through the
326		// chosen formatting.
327		for bits := uint64(0); bits < 200000; bits++ {
328			v := math.Float64frombits(bits)
329			if math.IsNaN(v) || math.IsInf(v, 0) {
330				continue
331			}
332			s := formatFloat(v)
333			back, err := strconv.ParseFloat(s, 64)
334			if err != nil || back != v {
335				t.Fatalf("formatFloat(%v) = %q, round-trips to %v, %v", v, s, back, err)
336			}
337		}
338	}
339	
340	func TestUnixNanoText(t *testing.T) {
341		cases := []struct {
342			t    time.Time
343			want string
344		}{
345			{time.Unix(0, 0).UTC(), "0"},
346			{time.Unix(0, 1).UTC(), "1"},
347			{time.Unix(0, -1).UTC(), "-1"},
348			{time.Unix(-1, 999999999).UTC(), "-1"},
349			{time.Unix(1, 0).UTC(), "1000000000"},
350		}
351		for _, tc := range cases {
352			if got := unixNanoText(tc.t); got != tc.want {
353				t.Fatalf("unixNanoText(%v) = %q, want %q", tc.t, got, tc.want)
354			}
355		}
356	}
