1	package rollup
2	
3	import (
4		"math"
5		"math/big"
6		"testing"
7		"time"
8	)
9	
10	// wantStart computes the epoch-aligned window start for at with 128-bit
11	// big-integer arithmetic, as an independent oracle for startOf.
12	func wantStart(at time.Time, w time.Duration) time.Time {
13		ns := big.NewInt(at.Unix())
14		ns.Mul(ns, big.NewInt(1e9))
15		ns.Add(ns, big.NewInt(int64(at.Nanosecond())))
16		wns := big.NewInt(w.Nanoseconds())
17		q := new(big.Int).Quo(ns, wns)
18		if new(big.Int).Rem(ns, wns).Sign() != 0 && ns.Sign() < 0 {
19			q.Sub(q, big.NewInt(1))
20		}
21		start := q.Mul(q, wns)
22		sec := new(big.Int).Quo(start, big.NewInt(1e9))
23		rem := new(big.Int).Rem(start, big.NewInt(1e9))
24		if rem.Sign() != 0 && start.Sign() < 0 {
25			sec.Sub(sec, big.NewInt(1))
26			rem.Add(rem, big.NewInt(1e9))
27		}
28		return time.Unix(sec.Int64(), rem.Int64()).UTC()
29	}
30	
31	// TestExtremeTimestampsAlign checks that samples far outside the int64
32	// nanosecond range still land in epoch-aligned windows.
33	func TestExtremeTimestampsAlign(t *testing.T) {
34		const window = 10 * time.Second
35		for _, at := range []time.Time{
36			time.Unix(1<<62, 123456789),       // far future, UnixNano overflows
37			time.Unix(-1<<62, 987654321),      // far past, UnixNano overflows
38			time.Unix(0, math.MaxInt64),       // largest representable nanos
39			time.Unix(0, math.MinInt64),       // smallest representable nanos
40			time.Unix(-9223372036, 999999999), // fast-path boundary
41			time.Unix(9223372036, 854775807),  // slow-path boundary
42		} {
43			r := New(window)
44			if err := r.Add(at, 5); err != nil {
45				t.Fatalf("Add(%v): %v", at, err)
46			}
47			want := wantStart(at, window)
48			w, ok := r.Window(want)
49			if !ok {
50				t.Fatalf("Add(%v): no window at aligned start %v", at, want)
51			}
52			if w.Count != 1 || w.Sum != 5 || w.Min != 5 || w.Max != 5 {
53				t.Fatalf("Add(%v): window %+v", at, w)
54			}
55			if got := r.Windows(); len(got) != 1 || !got[0].Start.Equal(want) {
56				t.Fatalf("Add(%v): Windows() = %v, want start %v", at, got, want)
57			}
58		}
59	}
60	
61	// TestMinWindowSize checks that a 1-nanosecond window behaves like any
62	// other size: boundary ownership, alignment, and lookup by start.
63	func TestMinWindowSize(t *testing.T) {
64		r := New(1)
65		for _, ns := range []int64{0, 0, 1, 2, 5} {
66			if err := r.Add(time.Unix(0, ns), float64(ns)); err != nil {
67				t.Fatal(err)
68			}
69		}
70		got := r.Windows()
71		if len(got) != 4 {
72			t.Fatalf("want 4 windows, got %d", len(got))
73		}
74		for i, ns := range []int64{0, 1, 2, 5} {
75			if !got[i].Start.Equal(time.Unix(0, ns)) {
76				t.Fatalf("window %d starts at %v, want %v", i, got[i].Start, time.Unix(0, ns))
77			}
78		}
79		w, ok := r.Window(time.Unix(0, 0))
80		if !ok || w.Count != 2 || w.Sum != 0 {
81			t.Fatalf("window 0: %+v ok=%v", w, ok)
82		}
83	}
84	
85	// TestCountSaturates checks that a window count at the int64 ceiling stops
86	// accumulating while sum, min, and max keep updating.
87	func TestCountSaturates(t *testing.T) {
88		r := New(time.Minute)
89		r.buckets = append(r.buckets, Window{
90			Start: time.Unix(0, 0).UTC(),
91			Count: math.MaxInt64,
92			Sum:   10,
93			Min:   1,
94			Max:   9,
95		})
96		r.latest = time.Unix(0, 0)
97		r.hasAny = true
98		if err := r.Add(time.Unix(0, 0), 20); err != nil {
99			t.Fatal(err)
100		}
101		w, _ := r.Window(time.Unix(0, 0))
102		if w.Count != math.MaxInt64 {
103			t.Fatalf("count overflowed: %d", w.Count)
104		}
105		if w.Sum != 30 || w.Min != 1 || w.Max != 20 {
106			t.Fatalf("stats did not keep updating: %+v", w)
107		}
108	}
109	
110	// TestMergeCountSaturates checks that merging counts past the int64
111	// ceiling clamps at the ceiling instead of wrapping.
112	func TestMergeCountSaturates(t *testing.T) {
113		a := New(time.Minute)
114		b := New(time.Minute)
115		start := time.Unix(0, 0).UTC()
116		a.buckets = append(a.buckets, Window{Start: start, Count: math.MaxInt64 - 1, Sum: 1, Min: 1, Max: 1})
117		b.buckets = append(b.buckets, Window{Start: start, Count: 10, Sum: 2, Min: 0, Max: 2})
118		if err := a.Merge(b); err != nil {
119			t.Fatal(err)
120		}
121		w, _ := a.Window(time.Unix(0, 0))
122		if w.Count != math.MaxInt64 {
123			t.Fatalf("count overflowed: %d", w.Count)
124		}
125		if w.Sum != 3 || w.Min != 0 || w.Max != 2 {
126			t.Fatalf("merged stats: %+v", w)
127		}
128	}
129	
130	// TestMergeSortedUnion cross-checks a large merge against a map-based
131	// oracle, including windows only one side has.
132	func TestMergeSortedUnion(t *testing.T) {
133		a := New(time.Second)
134		b := New(time.Second)
135		base := time.Unix(0, 0)
136		want := map[int64]Window{}
137		add := func(r *Roller, i int64, v float64) {
138			at := base.Add(time.Duration(i) * time.Second)
139			if err := r.Add(at, v); err != nil {
140				t.Fatal(err)
141			}
142			key := at.Unix()
143			w := want[key]
144			if w.Count == 0 {
145				w = Window{Start: at.UTC()}
146			}
147			w.Count++
148			w.Sum += v
149			if v < w.Min || w.Count == 1 {
150				w.Min = v
151			}
152			if v > w.Max || w.Count == 1 {
153				w.Max = v
154			}
155			want[key] = w
156		}
157		for i := int64(0); i < 5000; i++ {
158			if i%2 == 0 {
159				add(a, i, float64(i))
160			}
161			if i%2 == 1 || i%3 == 0 {
162				add(b, i, float64(-i))
163			}
164		}
165		if err := a.Merge(b); err != nil {
166			t.Fatal(err)
167		}
168		got := a.Windows()
169		if len(got) != len(want) {
170			t.Fatalf("got %d windows, want %d", len(got), len(want))
171		}
172		for i := 1; i < len(got); i++ {
173			if !got[i-1].Start.Before(got[i].Start) {
174				t.Fatalf("windows out of order at %d: %v then %v", i, got[i-1].Start, got[i].Start)
175			}
176		}
177		for _, w := range got {
178			if w != want[w.Start.Unix()] {
179				t.Fatalf("window %v: got %+v, want %+v", w.Start, w, want[w.Start.Unix()])
180			}
181		}
182	}
183	
184	// TestBackfillAfterMerge checks that samples earlier than merged-in windows
185	// can still be filed and land in the right place.
186	func TestBackfillAfterMerge(t *testing.T) {
187		a := New(time.Minute)
188		b := New(time.Minute)
189		if err := a.Add(time.Unix(0, 0), 1); err != nil {
190			t.Fatal(err)
191		}
192		for i := 100; i < 110; i++ {
193			if err := b.Add(time.Unix(int64(i)*60, 0), float64(i)); err != nil {
194				t.Fatal(err)
195			}
196		}
197		if err := a.Merge(b); err != nil {
198			t.Fatal(err)
199		}
200		// Backfill between the pre-merge sample and the merged windows.
201		for i := 1; i < 100; i++ {
202			if err := a.Add(time.Unix(int64(i)*60, 0), float64(i)); err != nil {
203				t.Fatalf("backfill %d: %v", i, err)
204			}
205		}
206		got := a.Windows()
207		if len(got) != 110 {
208			t.Fatalf("got %d windows, want 110", len(got))
209		}
210		for i, w := range got {
211			if !w.Start.Equal(time.Unix(int64(i)*60, 0)) {
212				t.Fatalf("window %d starts at %v", i, w.Start)
213			}
214		}
215	}
