func BenchmarkBackfillMass(b *testing.B) {
	for _, n := range []int{1000, 10000, 100000} {
		b.Run("", func(b *testing.B) {
			for i := 0; i < b.N; i++ {
				b.StopTimer()
				a := New(time.Minute)
				_ = a.Add(time.Unix(0, 0), 1)
				src := New(time.Minute)
