				for i := n; i >= 1; i-- {
					batch = append(batch, Sample{At: time.Unix(int64(i)*60, 0), 1})
				}
				b.StartTimer()
				if err := a.AddBatch(batch); err != nil {
					b.Fatal(err)
				}
			}
		})
		b.SetBytes(int64(n))
	}
}

