// TestConcurrentAddMergeQueryMillion runs the full mixed workload at the
// million scale: concurrent submission, folding merges racing the adds,
// and continuous snapshot/query traffic. Every accepted sample is
// accounted for exactly once, no window ever tears, and the window set
// stays ordered. Run with -race to catch data races.
func TestConcurrentAddMergeQueryMillion(t *testing.T) {
	if testing.Short() {
		t.Skip("million-sample concurrency run")
	}
	r := New(time.Second)
	const shards = 8
	const batchesPerShard = 15625
	const batchSize = 8 // 8 * 15625 * 8 = 1,000,000 samples

	// Window seconds are handed out strictly increasingly, so each
	// batch's instant is at or after the accepted marker no matter how
	// the shards interleave; every batch is accepted.
	var nextSecond atomic.Int64
	var mergedWindows atomic.Int64
	var accepted atomic.Int64

	stop := make(chan struct{})
	var readers sync.WaitGroup
	for i := 0; i < 2; i++ {
		readers.Add(1)
		go func() {
			defer readers.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				snap := r.Windows()
				for j := 1; j < len(snap); j++ {
					if !snap[j-1].Start.Before(snap[j].Start) {
						t.Errorf("window set out of order: %v then %v", snap[j-1].Start, snap[j].Start)
						return
					}
				}
				for _, w := range snap {
					if w.Count <= 0 || w.Min > w.Max {
						t.Errorf("torn window: %+v", w)
						return
					}
				}
				// A cursor over a snapshot moment must hand its windows
				// out exactly once and then end.
				c := r.Cursor(time.Unix(0, 0), time.Unix(1<<40, 0))
				var n int
				for batch := c.Next(4096); len(batch) != 0; batch = c.Next(4096) {
					for _, w := range batch {
						if w.Count <= 0 || w.Min > w.Max {
							t.Errorf("torn cursor window: %+v", w)
							return
						}
					}
					n += len(batch)
				}
				if tail := c.Next(8); len(tail) != 0 {
					t.Errorf("exhausted cursor moved: %+v", tail)
					return
				}
				_ = n
			}
		}()
	}

	var writers sync.WaitGroup
	for s := 0; s < shards; s++ {
		writers.Add(1)
		go func() {
			defer writers.Done()
			for i := 0; i < batchesPerShard; i++ {
				sec := nextSecond.Add(1) - 1
				batch := make([]Sample, batchSize)
				for k := range batch {
					batch[k] = Sample{At: time.Unix(sec, 0), Value: float64(sec)}
				}
				if err := r.AddBatch(batch); err != nil {
					t.Errorf("AddBatch: %v", err)
					return
				}
				accepted.Add(batchSize)
				// Periodically fold a roller with one window far ahead
				// of the sample stream: the merge races the other
				// writers, and afterwards new samples land through the
				// backfill map instead of the append path.
				if i&1023 == 0 {
					other := New(time.Second)
					if err := other.Add(time.Unix(int64(1<<30+i), 0), 1); err != nil {
						t.Errorf("other Add: %v", err)
						return
					}
					if err := r.Merge(other); err != nil {
						t.Errorf("Merge: %v", err)
						return
					}
					mergedWindows.Add(1)
				}
			}
		}()
	}
	writers.Wait()
	close(stop)
	readers.Wait()

	got := r.Windows()
	var total int64
	for _, w := range got {
		total += w.Count
	}
	if want := accepted.Load() + mergedWindows.Load(); total != want {
		t.Fatalf("total count %d, want %d accepted plus %d merged",
			total, accepted.Load(), mergedWindows.Load())
	}
	for i := 1; i < len(got); i++ {
		if !got[i-1].Start.Before(got[i].Start) {
			t.Fatalf("final windows out of order at %d: %v then %v",
				i, got[i-1].Start, got[i].Start)
		}
	}
}

