// TestMergeMismatchDiagnostic pins the one piece of merge output the
// contract writes to the letter: when the widths differ, the two file
// names appear in command-line order, separated by a comma and a space,
// on the single stderr diagnostic line, and the exit code stays 4. The
// mismatch is forced with two roller widths via two invocations is not
// possible through one --window, so the formatting is exercised through
// runMerge directly.
func TestMergeMismatchDiagnostic(t *testing.T) {
	dir := t.TempDir()
	pathA := filepath.Join(dir, "a.txt")
	pathB := filepath.Join(dir, "b.txt")
	if err := os.WriteFile(pathA, []byte("0 1\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(pathB, []byte("0 1\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	rollerA, code := ingestFile(pathA, time.Second, io.Discard)
	if code != 0 {
		t.Fatalf("ingest a: %d", code)
	}
	rollerB, code := ingestFile(pathB, time.Minute, io.Discard)
	if code != 0 {
		t.Fatalf("ingest b: %d", code)
	}
	var stdout, stderr bytes.Buffer
	// runMerge is the merge subcommand body; with mismatched widths it
	// must write exactly one diagnostic naming both files in order.
	rc := runMergeWith(rollerA, rollerB, pathA, pathB, &stdout, &stderr)
	if rc != 4 {
		t.Fatalf("code = %d, want 4", rc)
	}
	want := "rollupctl: " + pathA + ", " + pathB + ": rollup: window mismatch\n"
	if stderr.String() != want {
		t.Fatalf("stderr = %q, want %q", stderr.String(), want)
	}
	if strings.Count(strings.TrimRight(stderr.String(), "\n"), "\n") != 0 {
		t.Fatalf("stderr must be one line: %q", stderr.String())
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout must be empty: %q", stdout.String())
	}
}

